#!/usr/bin/env node
// Task-local replacement for the skill's email-contacts.js, using only Node built-ins.
// Performs authenticated GET /contacts and prints compact JSON on success.

const BASES = [
  process.env.EMAIL_API_BASE_URL,
  'https://agenskill-api.onrender.com',
  'https://agenskill.onrender.com',
].filter((b, i, arr) => b && arr.indexOf(b) === i);

async function main() {
  const args = process.argv.slice(2);
  const flag = (name) => {
    const idx = args.indexOf(`--${name}`);
    return idx >= 0 && idx + 1 < args.length ? args[idx + 1] : undefined;
  };

  const apiKey = flag('api-key');
  const userEmail = flag('user-email');
  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email');
  }

  let lastError = null;
  for (const base of BASES) {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 20000);
      const response = await fetch(`${base}/contacts`, {
        headers: { 'X-API-Key': apiKey, 'X-User-Email': userEmail },
        signal: controller.signal,
      });
      clearTimeout(timer);
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        lastError = new Error(`${base} -> ${response.status}: ${data.error || response.statusText}`);
        continue;
      }
      console.log(JSON.stringify({ success: true, base, count: (data.contacts || []).length, contacts: data.contacts || [] }));
      return;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error('No reachable API base URL');
}

main().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local, dependency-free replica of the registered email-api contacts helper
// (scripts/email-contacts.js) -- same documented argv, endpoint, headers, and output.
// The registered helper cannot run here because its `minimist` dependency is not
// installed in the environment.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token.startsWith('--')) {
      const key = token.slice(2);
      const value = argv[i + 1];
      args[key] = value === undefined ? true : value;
      i++;
    }
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

#!/usr/bin/env node
// Task-local equivalent of the email-api contacts helper, without the
// unavailable 'minimist' dependency. Only performs GET <base>/contacts
// using the documented X-API-Key / X-User-Email headers.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function argValue(name) {
  const flag = '--' + name;
  const idx = process.argv.indexOf(flag);
  return idx !== -1 ? process.argv[idx + 1] : undefined;
}

async function getContacts() {
  const apiKey = argValue('api-key');
  const userEmail = argValue('user-email');

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

getContacts()
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

#!/usr/bin/env node
// Task-local replacement for the email-api contacts helper.
// The registered helper (scripts/email-contacts.js) cannot run because the
// 'minimist' npm module is not installed in this environment. This script
// performs the identical documented operation: authenticated GET /contacts,
// using only Node's built-in fetch and simple argv parsing.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = argv[i].replace(/^--/, '');
    args[key] = argv[i + 1];
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
